// ProofOfDeliveryCreateBulk is the builder for creating many ProofOfDelivery entities in bulk.
type ProofOfDeliveryCreateBulk struct {
	config
	err      error
	builders []*ProofOfDeliveryCreate
	conflict []sql.ConflictOption
}

// Save creates the ProofOfDelivery entities in the database.
func (podcb *ProofOfDeliveryCreateBulk) Save(ctx context.Context) ([]*ProofOfDelivery, error) {
	if podcb.err != nil {
		return nil, podcb.err
	}
	specs := make([]*sqlgraph.CreateSpec, len(podcb.builders))
	nodes := make([]*ProofOfDelivery, len(podcb.builders))
	mutators := make([]Mutator, len(podcb.builders))
	for i := range podcb.builders {
		func(i int, root context.Context) {
			builder := podcb.builders[i]
			builder.defaults()
			var mut Mutator = MutateFunc(func(ctx context.Context, m Mutation) (Value, error) {
				mutation, ok := m.(*ProofOfDeliveryMutation)
				if !ok {
					return nil, fmt.Errorf("unexpected mutation type %T", m)
				}
				if err := builder.check(); err != nil {
					return nil, err
				}
				builder.mutation = mutation
				var err error
				nodes[i], specs[i] = builder.createSpec()
				if i < len(mutators)-1 {
					_, err = mutators[i+1].Mutate(root, podcb.builders[i+1].mutation)
				} else {
					spec := &sqlgraph.BatchCreateSpec{Nodes: specs}
					spec.OnConflict = podcb.conflict
					// Invoke the actual operation on the latest mutation in the chain.
					if err = sqlgraph.BatchCreate(ctx, podcb.driver, spec); err != nil {
						if sqlgraph.IsConstraintError(err) {
							err = &ConstraintError{msg: err.Error(), wrap: err}
						}
					}
				}
				if err != nil {
					return nil, err
				}
				mutation.id = &nodes[i].ID
				mutation.done = true
				return nodes[i], nil
			})
			for i := len(builder.hooks) - 1; i >= 0; i-- {
				mut = builder.hooks[i](mut)
			}
			mutators[i] = mut
		}(i, ctx)
	}
	if len(mutators) > 0 {
		if _, err := mutators[0].Mutate(ctx, podcb.builders[0].mutation); err != nil {
			return nil, err
		}
	}
	return nodes, nil
}

